/* Disposition de « Ma vie » : le personnage à gauche, les focus en haut au centre,
   les événements au centre. Ajoute aussi la vue « Repères » (comparaisons en %). */
tabs.splice(1,0,['standing','%','Repères']);navUnlock.standing=6;
const railBar=(label,v,good=true)=>`<div class="rail-stat"><div><span>${label}</span><b>${Math.round(v)}</b></div><div class="bar"><i style="width:${Math.max(0,Math.min(100,v))}%;background:${(good?v:100-v)<30?'var(--red)':'var(--green)'}"></i></div></div>`;
const pctLabel=r=>r.share?r.world.toLocaleString('fr-FR')+' %':Life.describePercentile(r.world);
function standRow(r){return`<div class="stand-row"><div class="stand-top"><span>${esc(r.label)}</span><b>${pctLabel(r)}</b></div><div class="pct-bar" title="${esc(r.display)}"><i style="left:${Math.max(1,Math.min(99,r.world))}%"></i></div></div>`}
function lineageCapital(p){return p.lineage?.applied?p.lineage.capital:Life.lineage.inheritedCapital(state,p).capital}
function characterRail(){const p=state.person,c=Life.country(state),s=state;
  const job=p.age<5?'Les premières années':p.age<16?'Enfance & découvertes':p.job;
  const worth=p.alive?Life.balance(p):p.finalWorth||0;
  const rows=p.age>=6?Life.standingHighlights(Life.standing(s).rows,3):[];
  const cap=lineageCapital(p);
  return`<aside class="char-rail"><section class="char-card"><div class="char-id"><div class="avatar pixel">${pixelAvatar(p)}</div><div><h2>${esc(p.name)} ${esc(p.surname)}</h2><small>${p.age} ans · ${state.year}</small></div></div>
<div class="char-meta"><span>⌖ ${esc(c.name)}</span><span>◌ ${esc(job)}</span><span>⑂ Génération ${state.generation}</span></div>
<div class="rail-stats">${railBar('Santé',p.health)}${railBar('Épanouissement',p.happiness)}${railBar('Énergie',p.energy)}${railBar('Stress',p.stress,false)}</div>
${p.age>=18?`<div class="rail-money"><span>Patrimoine net</span><b>${money(worth)}</b></div>`:''}
${p.statuses.length?`<div class="status-strip">${p.statuses.map(x=>`<span class="tag warning">${esc(x.label)} · ${x.years} an${x.years>1?'s':''}</span>`).join('')}</div>`:''}</section>
${rows.length?`<section class="char-card"><div class="rail-head"><h3>Parmi les autres</h3><button class="muted" onclick="nav('standing')">Tout ↗</button></div><small class="muted">Face à l’ensemble des humains</small>${rows.map(standRow).join('')}</section>`:''}
${p.age>=6?`<section class="char-card"><div class="rail-head"><h3>Capital de lignée</h3><b class="gold">${cap}</b></div><div class="bar"><i style="width:${cap}%;background:var(--gold)"></i></div><p class="hint">${p.lineage?.applied?'Réseau, nom et études transmis par vos aïeux.':'Se fixe à 18 ans, d’après ce que vos parents ont accompli.'}</p></section>`:''}
${p.age<6?`<section class="char-card"><h3>Votre premier univers</h3>${micro('Foyer',esc(p.birth.structure))}${micro('Cadre',p.birth.urban?'Milieu urbain':'Milieu rural')}${micro('Fratrie',p.birth.siblings)}<div class="family-portraits">${p.parents.map((x,i)=>`<div><div class="avatar pixel">${pixelAvatar({...x,age:28+i*4})}</div><small>${esc(x.name)}</small></div>`).join('')}</div></section>`:''}
<button class="pill rail-help" onclick="guide()">? &nbsp; Prendre en main</button></aside>`}
function focusStrip(){const p=state.person,next=nextUnlock();
  if(!p.alive)return'';
  const tiles=[];
  if(p.age>=5)tiles.push(`<div class="focus-tile"><span class="eyebrow">Temps</span><div class="time-blocks">${Array.from({length:Life.capacity(p)},(_,i)=>`<span class="${i<p.timeSpent?'spent':i<p.timeSpent+Life.projectEffort(p)?'reserved':'free'}"></span>`).join('')}</div><b>${Life.available(p)} créneau${Life.available(p)>1?'x':''} libre${Life.available(p)>1?'s':''}</b></div>`);
  if(p.age>=6)tiles.push(`<div class="focus-tile"><span class="eyebrow">Priorité de l’année</span><select aria-label="Priorité de l’année" onchange="act('focus',this.value)">${[['balance','Équilibre'],...(p.age>=18?[['career','Carrière & ambition']]:[]),['family','Proches & présence'],['health','Santé & récupération']].map(([v,t])=>`<option value="${v}" ${p.focus===v?'selected':''}>${t}</option>`).join('')}</select>${p.age>=18?`<small class="muted">Boussole : ${esc(goalLabels[p.goal]||'')}</small>`:''}</div>`);
  if(p.age>=8)tiles.push(`<div class="focus-tile wide"><span class="eyebrow">En construction</span>${p.projects.length?p.projects.slice(0,2).map(miniProject).join(''):`<small class="muted">Aucun projet.</small> <button class="muted" onclick="hubProjects()">Explorer ↗</button>`}</div>`);
  if(p.age>=18&&p.career)tiles.push(`<div class="focus-tile"><span class="eyebrow">Métier</span><b>${esc(p.job)}</b><small class="muted">${plain(p.salary)} UPA/an · ${p.career.years||0} an(s)</small></div>`);
  else if(p.age>=18)tiles.push(`<div class="focus-tile"><span class="eyebrow">Métier</span><b>Sans emploi</b><button class="muted" onclick="openHubJobs()">Voir les offres ↗</button></div>`);
  if(next)tiles.push(`<div class="focus-tile"><span class="eyebrow">Prochaine porte · ${next} ans</span><small class="muted">${{5:'Les relations prennent forme.',6:'Initiatives et habitudes.',8:'Premiers projets personnels.',16:'Formations et bourses.',18:'Travail, finances, indépendance.'}[next]}</small></div>`);
  return`<section class="focus-strip" aria-label="Focus de la vie">${tiles.join('')}</section>`}
function lifeCenter(){const s=state,p=s.person;const moments=s.journal.filter(x=>x.person===p.id).slice(-7).reverse();const last=s.journal.filter(x=>x.kind==='instant'&&x.person===p.id&&x.year===s.year).at(-1);
  return`<section class="life-center">${focusStrip()}${!p.alive?ending():s.pending?eventView():''}${last?`<div class="moment-card"><span class="eyebrow">${monthNames[Math.max(0,(last.month||1)-1)]} ${last.year} · Un instant de vie</span><p>${esc(last.text)}</p></div>`:''}${yearHub()}<div class="section-head"><h3>Le fil de votre vie</h3><button class="muted" onclick="nav('journal')">Tout relire ↗</button></div>${timeline(moments)}</section>`}
function cell(v,share){if(v==null)return'<td class="na">—</td>';return`<td><b>${share?v.toLocaleString('fr-FR')+' %':Life.describePercentile(v)}</b><div class="pct-bar"><i style="left:${Math.max(1,Math.min(99,v))}%"></i></div></td>`}
function lineageChain(){const chain=Life.lineage.chain(state);return`<div class="lineage-chain">${chain.map((x,i)=>`<article class="gen ${x.id===state.person.id?'current':''}"><span class="eyebrow">Génération ${state.generation-(chain.length-1-i)}</span><h4>${esc(x.name)}</h4><small>${esc(x.job||'')} · ${esc(Life.countries.find(c=>c.code===x.country)?.name||'')}</small><div class="bar"><i style="width:${x.capital??0}%;background:var(--gold)"></i></div><small>Capital ${x.capital??'—'} · réussite ${x.achievement}</small>${x.stigma?`<small class="negative">Réputation difficile ${x.stigma}</small>`:''}</article>`).join('<span class="gen-arrow">→</span>')}</div>`}
function standingView(){const s=state,p=s.person,st=Life.standing(s),c=Life.country(s);
  return`${heading('Où vous situez-vous ?','Votre place parmi les autres, selon quatre repères.',`<button class="pill" onclick="nav('life')">← Ma vie</button>`)}
<div class="card"><table class="stand-table"><thead><tr><th></th><th>Monde</th><th>${esc(c.name)}</th><th>Même âge · ${p.age} ans</th><th>${st.job?'Même métier':'Même métier'}${st.job?'<small>'+esc(st.job)+'</small>':''}</th></tr></thead><tbody>${st.rows.map(r=>`<tr><th><span>${esc(r.label)}</span><small>${esc(r.display)}</small></th>${cell(r.world,r.share)}${cell(r.country,r.share)}${cell(r.age,r.share)}${cell(r.job,r.share)}</tr>`).join('')}</tbody></table>
<p class="hint">« devant 73 % » : 73 % des personnes du groupe sont derrière vous. « Top 5 % » : vous faites partie des 5 % les mieux placés. Ce sont des distributions de jeu, calibrées sur les profils de pays du modèle, pas des statistiques officielles. Le métier ne compare que ce qui a un sens (revenu, ancienneté, compétence-clef).</p></div>
<div class="section-head" style="margin-top:28px"><h3>Votre lignée, génération après génération</h3></div>
<div class="card">${lineageChain()}<p class="hint">Chaque génération transmet la moitié de son capital et ajoute ce qu’elle a accompli : métier, patrimoine, études, notoriété, mandats. Une famille très pauvre part de presque rien ; ses descendants récoltent réseau, nom et études. Les très hautes fonctions restent ouvertes dès la première génération, mais avec très peu de chances. Un passé en marge (réseau criminel, détention) pèse aussi sur les descendants.</p></div>`}
lifeView=function(){if(page==='standing')return standingView();return`<div class="life-grid">${characterRail()}${lifeCenter()}</div>`};

/* ── Gamification : grands moments, gains visibles, succès et niveaux ── */
tabs.splice(2,0,['trophies','★','Trophées']);navUnlock.trophies=5;
const GRAND={school:['Entrée à l’école','Un nouveau monde s’ouvre.'],talent:['Une passion se révèle','Ce que vous faites quand personne ne vous y oblige.'],teen:['L’adolescence','Qui avez-vous envie de devenir ?'],adult:['La majorité','L’indépendance commence.'],turn30:['Trente ans','Vos ambitions sont-elles encore les vôtres ?'],turn50:['Cinquante ans','Ce qui mérite la suite.'],retirement:['La retraite','Votre temps peut changer de propriétaire.']};
const CAT_ICON={'Grand moment':'⭐',Enfance:'🧸',Adolescence:'🎒','Grand tournant':'🌗','Carrière':'💼',Argent:'💰','Santé':'🩺',Couple:'💞',Famille:'🏡','Amitié':'🤝',Engagement:'🌱',Rencontre:'✨','Investissement':'📊',Monde:'🌍',Entreprise:'🏢',Logement:'🏠','Vie personnelle':'🌿'};
const announced=new Set();
const isAnnounce=e=>!!e&&(e.announce||!!GRAND[e.id]);
const grandText=e=>e.announce?[e.big,e.sub]:GRAND[e.id];
const canDom=()=>typeof document!=='undefined'&&typeof document.createElement==='function'&&typeof document.body?.appendChild==='function';
function confetti(){if(!canDom()||(typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches))return;const layer=document.createElement('div');layer.className='confetti';layer.setAttribute('aria-hidden','true');const colors=['#c5df9c','#d9bd80','#e5a299','#9bc7d9','#e8ede6'];for(let i=0;i<42;i++){const b=document.createElement('span');b.style.cssText=`left:${Math.random()*100}%;background:${colors[i%colors.length]};animation-delay:${(Math.random()*.5).toFixed(2)}s;animation-duration:${(1.8+Math.random()*1.4).toFixed(2)}s;transform:rotate(${Math.floor(Math.random()*360)}deg)`;layer.appendChild(b)}document.body.appendChild(layer);setTimeout(()=>layer.remove(),3600)}
function closeAnnounce(){$('#modal').close()}
function maybeAnnounce(){if(!state||!state.person.alive||!state.birthRevealed||page!=='life')return;const e=state.pending;if(!isAnnounce(e))return;const key=state.person.id+'|'+e.id;if(announced.has(key)||$('#modal').open)return;announced.add(key);const[title,sub]=grandText(e);modal(`<div class="announce"><div class="announce-age">${state.person.age} ans</div><div class="eyebrow">${state.year} · Grand moment</div><h2>${esc(title)}</h2><p>${esc(sub)}</p><button class="btn primary" onclick="closeAnnounce()">Découvrir ›</button></div>`);confetti()}
/* Gains visibles après un choix */
const GAIN_LABELS={health:'Santé',happiness:'Épanouissement',energy:'Énergie',stress:'Stress',network:'Réseau',reputation:'Réputation'};
function snap(p){return{...p.skills,health:p.health,happiness:p.happiness,energy:p.energy,stress:p.stress,network:p.network,reputation:p.reputation,cash:p.cash}}
function gainChips(before,after){const out=[];for(const k of Object.keys(after)){if(k==='cash')continue;const d=Math.round(after[k]-(before[k]||0));if(!d)continue;const label=Life.skills[k]||GAIN_LABELS[k];if(!label)continue;const good=k==='stress'?d<0:d>0;out.push({label,d,good})}
  const dc=Math.round(after.cash-before.cash);if(Math.abs(dc)>=1)out.push({label:'Argent',d:dc,good:dc>0});return out.slice(0,6)}
function showGains(chips){if(!chips.length||!canDom())return;let layer=document.getElementById('gains');if(!layer){layer=document.createElement('div');layer.id='gains';layer.setAttribute('role','status');document.body.appendChild(layer)}layer.innerHTML=chips.map(c=>`<span class="gain ${c.good?'up':'down'}">${c.d>0?'+':'−'}${Math.abs(c.d).toLocaleString('fr-FR')} ${esc(c.label)}</span>`).join('');layer.classList.remove('show');void layer.offsetWidth;layer.classList.add('show');clearTimeout(showGains.t);showGains.t=setTimeout(()=>layer.classList.remove('show'),2600)}
const gainDecide=decide;decide=function(i){const before=state?snap(state.person):null,id=state?.person.id;gainDecide(i);if(before&&state&&state.person.id===id)showGains(gainChips(before,snap(state.person)))};
/* Succès débloqués : message et confettis */
function drainTrophies(){if(!state||!state.newTrophies?.length)return;const ids=state.newTrophies.splice(0);const items=ids.map(id=>Life.achievements.byId[id]).filter(Boolean);if(!items.length||!canDom())return;const box=document.createElement('div');box.className='trophy-toast';box.setAttribute('role','status');box.innerHTML=items.slice(0,3).map(t=>`<div><span class="ti">${t.icon}</span><div><small>Succès débloqué · +${t.pts} pts</small><b>${esc(t.name)}</b></div></div>`).join('')+(items.length>3?`<small>et ${items.length-3} autre(s)</small>`:'');document.body.appendChild(box);setTimeout(()=>box.classList.add('out'),3800);setTimeout(()=>box.remove(),4400);confetti()}
const baseRender=render;render=function(){baseRender();maybeAnnounce();drainTrophies()};
const baseEventView=eventView;eventView=function(){const e=state.pending,html=baseEventView();const icon=CAT_ICON[e.category]||'🌿';let out=html.replace(/<div class="eyebrow">/,`<div class="eyebrow"><span class="cat-icon">${icon}</span> `);if(!isAnnounce(e))out=out.replace('<article class="card event">','<article class="card event decision"><div class="your-turn"><i></i>À vous de choisir</div>');if(isAnnounce(e))out=out.replace('<article class="card event">',`<article class="card event grand-moment"><div class="grand-badge">★ Grand moment · ${state.person.age} ans</div>`);return out};
/* Niveau et succès dans la fiche du personnage */
const baseRail=characterRail;characterRail=function(){let html=baseRail();const lv=Life.achievements.level(state),n=Object.keys(state.trophies||{}).length,total=Life.achievements.list.length,next=Life.achievements.nextUp(state,2);
  const card=`<section class="char-card level-card"><div class="rail-head"><h3>Niveau ${lv.index} · ${lv.name}</h3><button class="muted" onclick="nav('trophies')">${n}/${total} ★</button></div><div class="bar"><i style="width:${Math.round(lv.progress*100)}%;background:var(--gold)"></i></div><small class="muted">${lv.to?`${lv.points} / ${lv.to} pts`:`${lv.points} pts · niveau maximal`}</small>${next.map(t=>`<div class="next-up"><span>${t.icon}</span><div><b>${esc(t.name)}</b><div class="bar"><i style="width:${Math.round(t.progress*100)}%"></i></div></div></div>`).join('')}</section>`;
  return html.replace('<aside class="char-rail">','<aside class="char-rail">').replace(/(<section class="char-card">[\s\S]*?<\/section>)/,`$1${card}`)};
function trophyView(){const s=state,lv=Life.achievements.level(s),list=Life.achievements.list,got=s.trophies||{},cats=[...new Set(list.map(t=>t.cat))];
  return`${heading('Vos trophées','Chaque vie laisse des traces. Collectionnez-les, génération après génération.',`<button class="pill" onclick="nav('life')">← Ma vie</button>`)}
<div class="card level-hero"><div><span class="eyebrow">Niveau ${lv.index}</span><h2>${lv.name}</h2><small class="muted">${lv.points} points${lv.to?` · encore ${lv.to-lv.points} pour « ${Life.achievements.levels[lv.index][0]} »`:''}</small></div><div class="level-bar"><div class="bar"><i style="width:${Math.round(lv.progress*100)}%;background:var(--gold)"></i></div><small>${Object.keys(got).length} / ${list.length} succès</small></div></div>
${cats.map(c=>`<div class="section-head" style="margin-top:22px"><h3>${c}</h3><small class="muted">${list.filter(t=>t.cat===c&&got[t.id]).length} / ${list.filter(t=>t.cat===c).length}</small></div><div class="trophy-grid">${list.filter(t=>t.cat===c).map(t=>{const g=got[t.id];return`<article class="trophy ${g?'got':'locked'}"><span class="ti">${g?t.icon:'🔒'}</span><div><b>${esc(t.name)}</b><small>${esc(t.desc)}</small>${g?`<small class="gold">${g.age} ans · ${g.year} · +${t.pts} pts</small>`:`<small>${t.pts} pts${t.prog?` · ${Math.round(t.prog(s,s.person)*100)} %`:''}</small>`}</div></article>`}).join('')}</div>`).join('')}`}
const lifeBeforeTrophy=lifeView;lifeView=function(){if(page==='trophies')return trophyView();return lifeBeforeTrophy()};

/* Hiérarchie : la frise se replie, la décision passe au premier plan */
const baseHUD=timelineHUD;timelineHUD=function(){return baseHUD().replace('<div class="live-date">','<div class="live-date" role="button" tabindex="0" title="Afficher ou masquer la frise" onclick="this.closest(\'.time-console\').classList.toggle(\'open\')">')};
